/// <summary>
/// Cash report Contract
/// </summary>
[DataContractAttribute]
internal final class AVARUMCashSalesSummaryContract  
{
    TransDate transDate;

}

Method.Source:
/// <summary>
/// Initializes a new instance of the <c>AVARUMCashSalesReportContract</c> class.
/// </summary>
protected void new()
{
    transDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// Gets or sets the transaction date parameter
/// </summary>
/// <param name="_transDate">Transaction date</param>
/// <returns>Transaction date</returns>
[DataMemberAttribute,
 SysOperationLabelAttribute(literalStr("@SYS115330")),
 SysOperationDisplayOrderAttribute('1')]
public TransDate parmTransDate(TransDate _transDate = transDate)
{
    transDate = _transDate;
    return transDate;
}
